#!/usr/bin/env python3
"""
Validation script for pipeline outputs.
Checks if expected output files exist, are non-empty, and contain expected data.
"""

import json
import os
import sys

# Configuration
OUTPUTS = {
    "t01_selected_indicators.csv": "outputs/t01_selected_indicators.csv",
    "t05_clean_stops.csv": "outputs/t05_clean_stops.csv",
    "t08_pois_clean.csv": "outputs/t08_pois_clean.csv",
    "t10_accessibility_scores.csv": "outputs/t10_accessibility_scores.csv",
    "t13_city_clusters.csv": "outputs/t13_city_clusters.csv",
}

VALIDATION_RESULTS = []


def check_file_exists(filepath):
    """Check if file exists."""
    if not os.path.exists(filepath):
        return False, f"File missing: {filepath}"
    return True, f"File exists: {filepath}"


def check_file_not_empty(filepath):
    """Check if file is not empty."""
    try:
        with open(filepath, 'r') as f:
            content = f.read()
            if len(content.strip()) == 0:
                return False, f"File is empty: {filepath}"
            return True, f"File has content: {filepath}"
    except Exception:
        return False, f"Cannot read file: {filepath}"


def check_indicators_present(filepath):
    """Check if indicators file has expected columns."""
    try:
        with open(filepath, 'r') as f:
            content = f.read()
            # Check for required columns
            if 'indicator_id' not in content:
                return False, "Missing indicator_id column"
            if 'indicator_name' not in content:
                return False, "Missing indicator_name column"
            if 'theme' not in content:
                return False, "Missing theme column"
            if 'justification' not in content:
                return False, "Missing justification column"
            if 'expected_direction' not in content:
                return False, "Missing expected_direction column"
            return True, "Indicators file has all required columns"
    except Exception:
        return False, "Cannot read indicators file"


def check_stops_present(filepath):
    """Check if stops file has required columns."""
    try:
        with open(filepath, 'r') as f:
            content = f.read()
            if 'stop_id' not in content:
                return False, "Missing stop_id column"
            if 'stop_name' not in content:
                return False, "Missing stop_name column"
            if 'stop_lat' not in content:
                return False, "Missing stop_lat column"
            if 'stop_lon' not in content:
                return False, "Missing stop_lon column"
            return True, "Stops file has all required columns"
    except Exception:
        return False, "Cannot read stops file"


def check_pois_present(filepath):
    """Check if POIs file has required columns."""
    try:
        with open(filepath, 'r') as f:
            content = f.read()
            if 'qid' not in content:
                return False, "Missing qid column"
            if 'label' not in content:
                return False, "Missing label column"
            if 'poi_type' not in content:
                return False, "Missing poi_type column"
            if 'latitude' not in content:
                return False, "Missing latitude column"
            if 'longitude' not in content:
                return False, "Missing longitude column"
            return True, "POIs file has all required columns"
    except Exception:
        return False, "Cannot read POIs file"


def check_accessibility_present(filepath):
    """Check if accessibility scores file has required columns."""
    try:
        with open(filepath, 'r') as f:
            content = f.read()
            if 'qid' not in content:
                return False, "Missing qid column"
            if 'label' not in content:
                return False, "Missing label column"
            if 'poi_type' not in content:
                return False, "Missing poi_type column"
            if 'distance_m' not in content:
                return False, "Missing distance_m column"
            if 'n_departures' not in content:
                return False, "Missing n_departures column"
            if 'n_routes' not in content:
                return False, "Missing n_routes column"
            return True, "Accessibility scores file has all required columns"
    except Exception:
        return False, "Cannot read accessibility scores file"


def check_city_clusters_present(filepath):
    """Check if city clusters file has required columns."""
    try:
        with open(filepath, 'r') as f:
            content = f.read()
            if 'city_id' not in content:
                return False, "Missing city_id column"
            if 'city_name' not in content:
                return False, "Missing city_name column"
            if 'year' not in content:
                return False, "Missing year column"
            if 'cluster_id' not in content:
                return False, "Missing cluster_id column"
            return True, "City clusters file has all required columns"
    except Exception:
        return False, "Cannot read city clusters file"


def run_validation():
    """Run all validation checks."""
    results = []

    # Check each output file
    for filename, output_path in OUTPUTS.items():
        filepath = os.path.join(OUTPUT_DIR, output_path)

        # Check file existence
        exists, msg = check_file_exists(filepath)
        if not exists:
            results.append({
                "check_name": filename,
                "passed": False,
                "message": msg
            })
            continue

        # Check if file is not empty
        if not os.path.exists(filepath):
            results.append({
                "check_name": filename,
                "passed": False,
                "message": msg
            })
            continue

        not_empty, msg = check_file_not_empty(filepath)
        if not not_empty:
            results.append({
                "check_name": filename,
                "passed": False,
                "message": msg
            })
            continue

        # Run specific checks based on output type
        if filename.startswith("t01"):
            indicators_ok, msg = check_indicators_present(filepath)
            if not indicators_ok:
                results.append({
                    "check_name": filename,
                    "passed": False,
                    "message": msg
                })
            else:
                results.append({
                    "check_name": filename,
                    "passed": True,
                    "message": msg
                })

        elif filename.startswith("t05"):
            stops_ok, msg = check_stops_present(filepath)
            if not stops_ok:
                results.append({
                    "check_name": filename,
                    "passed": False,
                    "message": msg
                })
            else:
                results.append({
                    "check_name": filename,
                    "passed": True,
                    "message": msg
                })

        elif filename.startswith("t08"):
            pois_ok, msg = check_pois_present(filepath)
            if not pois_ok:
                results.append({
                    "check_name": filename,
                    "passed": False,
                    "message": msg
                })
            else:
                results.append({
                    "check_name": filename,
                    "passed": True,
                    "message": msg
                })

        elif filename.startswith("t10"):
            accessibility_ok, msg = check_accessibility_present(filepath)
            if not accessibility_ok:
                results.append({
                    "check_name": filename,
                    "passed": False,
                    "message": msg
                })
            else:
                results.append({
                    "check_name": filename,
                    "passed": True,
                    "message": msg
                })

        elif filename.startswith("t13"):
            clusters_ok, msg = check_city_clusters_present(filepath)
            if not clusters_ok:
                results.append({
                    "check_name": filename,
                    "passed": False,
                    "message": msg
                })
            else:
                results.append({
                    "check_name": filename,
                    "passed": True,
                    "message": msg
                })

    # Write validation summary JSON to outputs/t14_validation_summary.json
    summary = {
        "checks": results
    }

    # Write to the required output file
    os.makedirs(OUTPUT_DIR, exist_ok=True)
    output_path = os.path.join(OUTPUT_DIR, "t14_validation_summary.json")
    with open(output_path, 'w') as f:
        json.dump(summary, f, indent=2)

    # Also print to stdout
    print(json.dumps(summary, indent=2))

    return summary


if __name__ == "__main__":
    run_validation()
    sys.exit(0)

